import contextlib
import logging
from typing import Iterator

logger = logging.getLogger(__name__)

@contextlib.contextmanager
def safe_resource_session(name: str) -> Iterator[dict]:
    session = {"name": name, "status": "active"}
    try:
        yield session
    except Exception as exc:
        logger.error("Session %s failed: %s", name, exc)
        raise
    finally:
        session["status"] = "closed"
        logger.info("Session %s safely terminated.", name)

